SELECT DISTINCT pt.requirement_id FROM requirement_pending_tasks pt LEFT JOIN (SELECT DISTINCT role_id FROM user_roles WHERE user_id = #{userId}) ur ON ur.role_id = pt.role_id LEFT JOIN (SELECT DISTINCT r.role_group_id FROM roles r JOIN user_roles ru ON r.id = ru.role_id AND ru.user_id = #{userId}) rg ON rg.role_group_id = pt.role_group_id LEFT JOIN (SELECT DISTINCT org_id FROM user_organizations WHERE user_id = #{userId}) uo ON uo.org_id = pt.org_id WHERE ( pt.user_id = #{userId} OR ur.role_id IS NOT NULL OR rg.role_group_id IS NOT NULL OR uo.org_id IS NOT NULL )
AND EXISTS ( SELECT 1 FROM requirements r WHERE r.id = pt.requirement_id AND r.project_id = #{projectId} )
ORDER BY pt.updated_at DESC LIMIT #{limit}

